/*
 * prog16_word_count_fsm – reconstructed implementation
 *
 * The original binary implements a tiny finite‑state machine that reads
 * stdin one byte at a time and keeps three counters:
 *
 *   • LINES – number of '\n' characters seen
 *   • WORDS – number of transitions from a word to a whitespace
 *   • CHARS – total number of characters read (EOF is not counted)
 *
 * A “word” is any maximal sequence of characters that are **not**
 * whitespace (space, tab or newline).  The word counter is only
 * incremented when a whitespace character is encountered *after* a
 * word; a word that ends exactly at EOF is **not** counted – this
 * matches the behaviour of the original FSM.
 *
 * At the end the program prints the three counters in the exact format
 * used by the original binary:
 *
 *     LINES=%ld WORDS=%ld CHARS=%ld\n
 *
 * The code below reproduces that observable behaviour in a clear,
 * idiomatic C style.
 */

#include <stdio.h>

int main(void)
{
    long lines = 0;   /* LINES */
    long words = 0;   /* WORDS */
    long chars = 0;   /* CHARS */

    int c;
    int in_word = 0;          /* 0 = currently in whitespace, 1 = inside a word */

    while ((c = getc(stdin)) != EOF) {
        ++chars;               /* count every character read */

        if (c == '\n')
            ++lines;           /* newline → line counter */

        /* whitespace characters recognised by the original FSM */
        if (c == ' ' || c == '\t' || c == '\n') {
            if (in_word) {     /* we just left a word */
                ++words;
                in_word = 0;
            }
        } else {
            in_word = 1;       /* we are inside a word */
        }
    }

    /* NOTE: the original program does NOT count a trailing word that
       ends at EOF, so we deliberately do NOT add a final word here. */

    printf("LINES=%ld WORDS=%ld CHARS=%ld\n", lines, words, chars);
    return 0;
}
